import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.BXzK3EA4.js";const f=JSON.parse('{"title":"How to transfer data in a Linux system","description":"","frontmatter":{"title":"How to transfer data in a Linux system"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/linux/how-to-transfer-data-in-a-linux-system.md","filePath":"operations-knowledge-base/operating-system/linux/how-to-transfer-data-in-a-linux-system.md","lastUpdated":1794292919000}'),p={name:"operations-knowledge-base/operating-system/linux/how-to-transfer-data-in-a-linux-system.md"};function n(i,e,s,c,l,m){return t(),r("div",null,[...e[0]||(e[0]=[a('<p>The <code>scp</code> command is used for remote file copying in Linux. It allows copying files or directories between multiple Linux systems, similar to the functionality of the <em><code>cp</code></em> command. But instead of local copying, it operates to another host over the network.</p><p>Syntax format: scp [parameters] file_or_directory [remote_server_info]</p><p>Common parameters:</p><p>-1：Use SSH protocol version 1；</p><p>-2：Use SSH protocol version 2；</p><p>-4：Use ipv4；</p><p>-6：Use ipv6；</p><p>-B：Run in batch mode；</p><p>-C：Use compression；</p><p>-F：Specify the SSH configuration file；</p><p>-i：identity_file Read the key file used for the transfer from the specified file (e.g., Amazon Cloud <code>.pem</code> file); this parameter is passed directly to SSH；</p><p>-l：Specify bandwidth limit；</p><p>-o：Specify the SSH options to use；</p><p>-P：Specify the port of the remote host；</p><p>-p：Preserve the file&#39;s last modification time, last access time, and permission mode；</p><p>-q：Do not display the copy progress；</p><p>-r：Copy recursively。</p><p><strong>Parameters</strong></p><ul><li>Source file: Specify the source file to be copied.</li><li>Destination file: The target file. The format is <em>user@host:filename</em> (where filename is the name of the target file).</li></ul><p>Example</p><p>The scp command to copy from remote to local is similar to the one above; you just need to swap the order of the last two parameters.</p><p><strong>1.Copy files from a remote machine to the local directory</strong></p><p>scp <a href="mailto:root@10.10.10.10" target="_blank" rel="noreferrer">root@10.10.10.10</a>:/opt/soft/nginx-0.5.38.tar.gz /opt/soft/</p><p>Download the <em><code>nginx-0.5.38.tar.gz</code></em> file from the <em><code>/opt/soft/</code></em> directory on the machine <code>10.10.10.10</code> to the local <em><code>/opt/soft/</code></em> directory.</p><p><strong>2.Copy OpenVPN from Amazon Cloud to the local directory</strong></p><p>scp -i amazon.pem <a href="mailto:ubuntu@10.10.10.10" target="_blank" rel="noreferrer">ubuntu@10.10.10.10</a>:/usr/local/openvpn_as/etc/exe/openvpn-connect-2.1.3.110.dmg openvpn-connect-2.1.3.110.dmg</p><p>Download the OpenVPN installation file from the machine <code>10.10.10.10</code> to the current local directory.</p><p><strong>3.Copy from a remote machine to the local machine</strong></p><p>scp -r <a href="mailto:root@10.10.10.10" target="_blank" rel="noreferrer">root@10.10.10.10</a>:/opt/soft/mongodb /opt/soft/</p><p>Download the <em><code>mongodb</code></em> directory from <em><code>/opt/soft/</code></em> on the machine <code>10.10.10.10</code> to the local <em><code>/opt/soft/</code></em> directory.</p><p><strong>4.Upload a local file to a specified directory on a remote machine.</strong></p><p>scp /opt/soft/nginx-0.5.38.tar.gz <a href="mailto:root@10.10.10.10" target="_blank" rel="noreferrer">root@10.10.10.10</a>:/opt/soft/scptest</p><h2 id="specify-the-port-2222" tabindex="-1">Specify the port 2222 <a class="header-anchor" href="#specify-the-port-2222" aria-label="Permalink to &quot;Specify the port 2222&quot;">​</a></h2><p>scp -rp -P 2222 /opt/soft/nginx-0.5.38.tar.gz <a href="mailto:root@10.10.10.10" target="_blank" rel="noreferrer">root@10.10.10.10</a>:/opt/soft/scptest</p><p>Copy the <em><code>nginx-0.5.38.tar.gz</code></em> file from the local <em><code>/opt/soft/</code></em> directory to the <em><code>/opt/soft/scptest</code></em> directory on the remote machine <code>10.10.10.10</code>.</p><p><strong>5.Upload a local directory to a specified one on a remote machine.</strong></p><p>scp -r /opt/soft/mongodb <a href="mailto:root@10.10.10.10" target="_blank" rel="noreferrer">root@10.10.10.10</a>:/opt/soft/scptest</p><p>Upload the local directory <em><code>/opt/soft/mongodb</code></em> to the <em><code>/opt/soft/scptest</code></em> directory on the remote machine <code>10.10.10.10</code>.</p>',38)])])}const h=o(p,[["render",n]]);export{f as __pageData,h as default};
